D = (1,3);
V = (0,4);
R = reflect((0,0),D)*(V);
P = (V + R)/2;

draw((-1,0)--(3,0));
draw((0,-1)--(0,5));
draw((0,0)--D,Arrow(6));
draw((0,0)--V,red,Arrow(6));
draw((0,0)--R,blue,Arrow(6));
draw((0,0)--P,green,Arrow(6));
