draw(surface(P--Q--R--cycle),paleyellow,nolight);
draw(surface(P--S--T--cycle),paleyellow,nolight);
draw(surface(P--U--V--cycle),paleyellow,nolight);
draw((1,0,0)--(0,1,0)--(0,0,1)--cycle);
