  return (-2*sin(pi*x));
}

draw(graph(func,-2,2),red);
draw(reflect((0,0),(1,1))*(graph(func,-2,2)),blue);
draw((-2.5,0)--(2.5,0));
draw((0,-2.5)--(0,2.5));

draw((1,-0.1)--(1,0.1));
draw((2,-0.1)--(2,0.1));
draw((-1,-0.1)--(-1,0.1));
draw((-2,-0.1)--(-2,0.1));
draw((-0.1,1)--(0.1,1));
draw((-0.1,2)--(0.1,2));
draw((-0.1,-1)--(0.1,-1));
